<script setup lang="ts">
import QuoteSubscription from '../../components/QuoteSubscription.vue'
import { ref,watch } from 'vue'
import { onShow } from '@dcloudio/uni-app'
import { request,upload,idempotencyKey,priorities } from '../../api'
import { useSession } from '../../stores/session'
const facilityScope=ref('PRIVATE'),locationText=ref('')
const bindings=ref<any[]>([]),categories=ref<any[]>([]),bi=ref(-1),ci=ref(-1),priority=ref('NORMAL'),title=ref(''),description=ref(''),images=ref<{path:string,id:string}[]>([]),busy=ref(false),uploading=ref(false),analyzing=ref(false),suggestion=ref<any>(null),attempt=ref<{hash:string,key:string}|null>(null),appointmentDate=ref(''),appointmentStart=ref(''),appointmentEnd=ref('')
onShow(async()=>{if(!useSession().requireLogin('RESIDENT'))return;const selectedRoomId=bindings.value[bi.value]?.roomId;bindings.value=(await request('/room-bindings')).records.filter((b:any)=>b.status==='APPROVED').map((b:any)=>({...b,label:`${b.communityName} ${b.buildingNo}栋${b.roomNo}室`}));bi.value=bindings.value.findIndex(b=>b.roomId===selectedRoomId);if(bi.value<0&&bindings.value.length)bi.value=0;if(!bindings.value.length)bi.value=-1;if(!categories.value.length)categories.value=await request('/repair/categories')})
async function selectImages(){if(images.value.length>=9)return;const result=await new Promise<UniApp.ChooseImageSuccessCallbackResult>((resolve,reject)=>uni.chooseImage({count:9-images.value.length,sizeType:['compressed'],success:resolve,fail:reject}));uploading.value=true;try{for(const path of result.tempFilePaths){const id=await upload(path);images.value.push({path,id})}}finally{uploading.value=false}}
const adoptedAnalysisId=ref('')
let analysisVersion=0
watch(description,()=>{analysisVersion++;suggestion.value=null},{flush:'sync'})
async function analyze(){if(analyzing.value)return;if(!description.value.trim()){uni.showToast({title:'先描述一下遇到的问题',icon:'none'});return}const original=description.value,version=++analysisVersion;analyzing.value=true;try{const result=await request('/ai/repair-analysis','POST',{description:original});if(version===analysisVersion&&description.value===original)suggestion.value=result}finally{analyzing.value=false}}
function adopt(){const result=suggestion.value;if(!result||result.source!=='AI')return;adoptedAnalysisId.value=result.analysisId;if(result.priority)priority.value=result.priority;if(result.categoryId)ci.value=categories.value.findIndex(c=>c.id===result.categoryId);suggestion.value=null}
async function submit(){if(bi.value<0||ci.value<0||!title.value.trim()||!description.value.trim()){uni.showToast({title:'请填写标题、描述、房屋与分类',icon:'none'});return}if(facilityScope.value==='PUBLIC'&&!locationText.value.trim()){uni.showToast({title:'请填写公共设施实际位置',icon:'none'});return}const body:any={facilityScope:facilityScope.value,locationText:locationText.value,roomId:bindings.value[bi.value].roomId,categoryId:categories.value[ci.value].id,title:title.value,description:description.value,priority:priority.value,attachmentIds:images.value.map(i=>i.id)};if(adoptedAnalysisId.value)body.analysisId=adoptedAnalysisId.value;if(appointmentDate.value){if(!appointmentStart.value||!appointmentEnd.value){uni.showToast({title:'请填写预约起止时间',icon:'none'});return}body.appointmentStartAt=`${appointmentDate.value}T${appointmentStart.value}:00+08:00`;body.appointmentEndAt=`${appointmentDate.value}T${appointmentEnd.value}:00+08:00`}const hash=JSON.stringify(body);if(!attempt.value||attempt.value.hash!==hash)attempt.value={hash,key:idempotencyKey()};busy.value=true;try{const order=await request('/repair/orders','POST',body,attempt.value.key);uni.redirectTo({url:`/pages/detail/index?id=${order.id}`})}finally{busy.value=false}}
</script>
<template><view class="page"><view class="eyebrow">把问题告诉我们</view><view class="page-title">提交报修</view><view v-if="!bindings.length" class="notice">你还没有审核通过的房屋。<text class="link" @click="uni.navigateTo({url:'/pages/bindings/index'})">去申请绑定 →</text></view><view class="card"><view class="label">设施归属（物业审核确认）</view><view class="tab-row"><text :class="{active:facilityScope==='PRIVATE'}" @click="facilityScope='PRIVATE'">自有设施 · 确认报价后维修</text><text :class="{active:facilityScope==='PUBLIC'}" @click="facilityScope='PUBLIC'">公共设施 · 居民免付</text></view><view class="label">{{facilityScope==='PUBLIC'?'所在小区的已绑定房屋（身份凭证）':'报修房屋'}}</view><picker :range="bindings" range-key="label" @change="bi=Number($event.detail.value)"><view class="field">{{bi>=0?bindings[bi].label:'请选择已审核的房屋'}}</view></picker><view v-if="facilityScope==='PUBLIC'" class="label">公共设施实际位置</view><input v-if="facilityScope==='PUBLIC'" v-model="locationText" class="field" maxlength="200" placeholder="例如3号楼一层电梯口"/><view class="label">报修标题</view><input v-model="title" maxlength="100" class="field" placeholder="例如：厨房水管漏水"/><view class="label">问题描述</view><textarea v-model="description" maxlength="2000" class="field textarea" placeholder="发生在什么位置？有什么现象？请尽量详细描述" @input="suggestion=null"/><button class="secondary" :loading="analyzing" :disabled="analyzing" @click="analyze">分析分类与紧急程度</button><view v-if="suggestion" class="notice"><view>{{suggestion.source==='AI'?'分类与紧急程度建议':'暂时无法分析，可继续人工填写'}}</view><view class="small">报修描述保留你的原文，采用建议只更新分类与紧急程度。</view><view v-if="suggestion.safetyNotice" class="spaced">{{suggestion.safetyNotice}}</view><view class="small spaced">建议仅供参考；未提示险情不代表已排除风险，实际情况请联系人工确认。</view><view v-if="suggestion.source==='AI'" class="small spaced">建议分类：{{categories.find(c=>c.id===suggestion.categoryId)?.name||'请人工选择'}} · 紧急程度：{{priorities[suggestion.priority]||'请人工选择'}}</view><button v-if="suggestion.source==='AI'" class="secondary" @click="adopt">采用建议</button></view><QuoteSubscription v-if="facilityScope==='PRIVATE'"/><view class="label">维修分类</view><picker :range="categories" range-key="name" @change="ci=Number($event.detail.value)"><view class="field">{{ci>=0?categories[ci].name:'请选择分类'}}</view></picker><view class="label">紧急程度</view><view class="tab-row"><text v-for="(name,value) in priorities" :key="value" :class="{active:priority===value}" @click="priority=value">{{name}}</text></view><view class="label">期望上门时间（选填）</view><picker mode="date" @change="appointmentDate=$event.detail.value"><view class="field">{{appointmentDate||'选择日期'}}</view></picker><view v-if="appointmentDate" class="row spaced"><picker mode="time" @change="appointmentStart=$event.detail.value"><view class="field">{{appointmentStart||'开始时间'}}</view></picker><picker mode="time" @change="appointmentEnd=$event.detail.value"><view class="field">{{appointmentEnd||'结束时间'}}</view></picker><text class="link" @click="appointmentDate=''">清除</text></view><view class="label">故障图片（最多9张）</view><view class="photo-grid"><view v-for="(image,index) in images" :key="image.id" @click="images.splice(index,1)"><image :src="image.path" mode="aspectFill"/><view class="small">点击移除</view></view></view><button class="secondary" :loading="uploading" :disabled="uploading||images.length>=9" @click="selectImages">添加图片</button></view><button class="primary" :loading="busy" :disabled="busy||uploading||!bindings.length" @click="submit">提交报修</button><view class="notice">预约时间为期望上门时间，物业将与你协调。提交后可在工单中查看维修进度。</view></view></template>
